function numIslands(grid: string[][]): number {
  const m = grid.length;
  const n = grid[0].length;
  const dirs = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1],
  ];
  let islands = 0;

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      // Нашли непосещённую сушу — это новый остров
      if (grid[i][j] !== '1') continue;
      islands++;

      // «Затапливаем» весь остров, чтобы не посчитать его повторно.
      // Явный стек вместо рекурсии: остров может быть до 90 000 клеток
      grid[i][j] = '0';
      const stack: number[][] = [[i, j]];
      while (stack.length) {
        const [r, c] = stack.pop()!;
        for (const [dr, dc] of dirs) {
          const nr = r + dr;
          const nc = c + dc;
          if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === '1') {
            // Помечаем при добавлении в стек, чтобы клетка не попала туда дважды
            grid[nr][nc] = '0';
            stack.push([nr, nc]);
          }
        }
      }
    }
  }

  return islands;
}

// Время: O(m · n) — каждая клетка затапливается один раз
// Память: O(m · n) — стек в худшем случае (вся сетка — суша)
